 public function __construct(private ?BaseConnection$db=null,private ?LocalEvidenceStorageService$storage=null,private ?OrganizationalAuthorityResolver$authority=null){$this->db??=db_connect();$this->storage??=new LocalEvidenceStorageService();$this->authority??=new OrganizationalAuthorityResolver($this->db);}
 public function correct(array$actor,string$id,array$input,?UploadedFile$file):array
 {
  $this->assertHr($actor);$type=(string)($input['correction_type']??'');if(!in_array($type,['data','substantive'],true))throw new InvalidArgumentException('CORRECTION_TYPE_REQUIRED');$reason=trim((string)($input['reason']??''));if($reason==='')throw new InvalidArgumentException('CORRECTION_REASON_REQUIRED');
  $original=$this->record($id);if(in_array($original['status'],['corrected','cancelled'],true))throw new RuntimeException('RANK_RECORD_NOT_CORRECTABLE');$history=$this->db->table('personnel_rank_history')->where('approved_rank_record_id',$id)->get()->getRowArray();if(!$history)throw new RuntimeException('RANK_HISTORY_NOT_FOUND');
  $rankCode=trim((string)($input['approved_rank_code']??$original['approved_rank_code']));$rank=$this->db->table('faculty_rank_catalog')->where(['rank_code'=>$rankCode,'is_active'=>1])->get()->getRowArray();if(!$rank)throw new InvalidArgumentException('CORRECTED_RANK_NOT_SYSTEM_VALID');$rankChanged=$rankCode!==$original['approved_rank_code'];if($type==='data'&&$rankChanged)throw new InvalidArgumentException('RANK_CHANGE_REQUIRES_SUBSTANTIVE_CORRECTION');if($rankChanged&&!$this->systemValidOption($original,$rankCode))throw new InvalidArgumentException('CORRECTED_RANK_OUTSIDE_SYSTEM_VALID_OPTIONS');$approval=$this->date((string)($input['approval_date']??$original['approval_date']),'CORRECTED_APPROVAL_DATE_INVALID');$effective=$this->date((string)($input['effectivity_date']??$original['effectivity_date']),'CORRECTED_EFFECTIVITY_DATE_INVALID');$isPending=in_array($original['status'],['approved_pending_effectivity','activation_failed','correction_pending'],true);
  if($isPending&&$effective<=date('Y-m-d'))throw new RuntimeException('CORRECTED_PENDING_EFFECTIVITY_MUST_BE_FUTURE');if(!$isPending&&$effective!==$original['effectivity_date'])throw new RuntimeException('HISTORICAL_TIMELINE_REBASE_REQUIRES_EXPLICIT_POLICY');$reuse=filter_var($input['reuse_original_document']??false,FILTER_VALIDATE_BOOLEAN);$stillSupports=filter_var($input['original_document_still_supports']??false,FILTER_VALIDATE_BOOLEAN);if($rankChanged&&$reuse&&!$stillSupports)throw new InvalidArgumentException('NEW_DOCUMENT_REQUIRED_FOR_SUBSTANTIVE_CORRECTION');
  $newId=$this->uuid();$stored=$this->document($original,$file,$reuse,$newId);$status=$isPending?'approved_pending_effectivity':$original['status'];$newHistoryStatus=$history['status']==='current'?'current':($isPending?'pending':'historical');$this->assertNoOverlap($original,$history,$effective,$history['effective_to'],$newHistoryStatus);
  $actorId=(string)$actor['profile']['id'];$now=date('Y-m-d H:i:s');$this->db->transBegin();try{$locked=$this->lock($id);if($locked['status']!==$original['status'])throw new RuntimeException('RANK_RECORD_CHANGED_DURING_CORRECTION');$this->event($id,'correction_initiated',$actorId,['correction_type'=>$type]);$this->db->table('personnel_approved_rank_records')->where('id',$id)->update(['status'=>'corrected']);$this->db->table('personnel_rank_history')->where('id',$history['id'])->update(['status'=>'corrected']);$row=$original;unset($row['id'],$row['pending_personnel_guard'],$row['original_case_guard']);$row=array_merge($row,['id'=>$newId,'source_approved_rank_record_id'=>$id,'record_kind'=>'correction','correction_type'=>$type,'approved_rank_code'=>$rankCode,'approval_date'=>$approval,'effectivity_date'=>$effective,'status'=>$status,'signed_document_storage_path'=>$stored['storage_path'],'signed_document_original_name'=>$stored['original_name'],'signed_document_mime_type'=>$stored['mime'],'signed_document_sha256'=>$stored['sha256'],'signed_document_byte_size'=>$stored['bytes'],'recorded_by_profile_id'=>$actorId,'recorded_at'=>$now,'activated_at'=>$newHistoryStatus==='current'?$now:null,'activation_failure_code'=>null,'activation_failure_reason'=>null,'last_activation_attempt_at'=>null,'recovery_reason'=>null]);$this->db->table('personnel_approved_rank_records')->insert($row);$this->db->table('personnel_rank_history')->insert(['id'=>$this->uuid(),'approved_rank_record_id'=>$newId,'personnel_profile_id'=>$original['personnel_profile_id'],'rank_code'=>$rankCode,'effective_from'=>$effective,'effective_to'=>$history['effective_to'],'status'=>$newHistoryStatus]);$correctionId=$this->uuid();$action=$reuse?'original_reused':'new_document_supplied';$this->db->table('personnel_rank_corrections')->insert(['id'=>$correctionId,'original_approved_rank_record_id'=>$id,'corrected_approved_rank_record_id'=>$newId,'correction_type'=>$type,'reason'=>$reason,'document_action'=>$action,'performed_by_profile_id'=>$actorId,'completed_at'=>$now]);$this->event($newId,$reuse?'correction_document_reused':'correction_document_supplied',$actorId,['original_record_id'=>$id]);$this->event($newId,'correction_linked',$actorId,['original_record_id'=>$id,'correction_id'=>$correctionId]);if($isPending)$this->event($newId,'replacement_pending_created',$actorId,['effectivity_date'=>$effective]);if($newHistoryStatus==='current')$this->db->table('personnel_profiles')->where('profile_id',$original['personnel_profile_id'])->update(['current_rank_title'=>$rank['display_label'],'updated_at'=>$now]);$this->event($newId,'correction_completed',$actorId,['correction_type'=>$type,'document_action'=>$action]);$this->db->transCommit();$this->notify($original['personnel_profile_id'],$newId,'rank_record_corrected','Rank record corrected','A formal '.$type.' correction was completed. Reason: '.$reason);return$this->record($newId);}catch(\Throwable$e){$this->db->transRollback();if(!$reuse&&isset($stored['storage_path']))$this->storage->deletePhysicalFile($stored['storage_path']);throw$e;}
 }
 public function cancel(array$actor,string$id,string$reason):array{$this->assertHr($actor);$reason=trim($reason);if($reason==='')throw new InvalidArgumentException('CANCELLATION_REASON_REQUIRED');$r=$this->record($id);if(!in_array($r['status'],['approved_pending_effectivity','cancellation_pending'],true)||$r['effectivity_date']<=date('Y-m-d'))throw new RuntimeException('ONLY_FUTURE_PENDING_RANK_CAN_BE_CANCELLED');$actorId=(string)$actor['profile']['id'];$this->db->transBegin();try{$locked=$this->lock($id);if($locked['status']!==$r['status'])throw new RuntimeException('RANK_RECORD_CHANGED_DURING_CANCELLATION');$this->db->table('personnel_approved_rank_records')->where('id',$id)->update(['status'=>'cancelled','recovery_reason'=>$reason]);$this->db->table('personnel_rank_history')->where(['approved_rank_record_id'=>$id,'status'=>'pending'])->update(['status'=>'cancelled']);$this->event($id,'cancellation',$actorId,['reason'=>$reason]);$this->db->transCommit();$this->notify($r['personnel_profile_id'],$id,'pending_rank_cancelled','Pending approved rank cancelled','Your pending approved rank was cancelled. Reason: '.$reason);return$this->record($id);}catch(\Throwable$e){$this->db->transRollback();throw$e;}}
 public function history(array$actor,string$personnel):array{$records=$this->db->table('personnel_approved_rank_records')->where('personnel_profile_id',$personnel)->orderBy('effectivity_date','DESC')->orderBy('recorded_at','DESC')->get()->getResultArray();if($this->isHr($actor)||$this->owner($actor,$personnel))return array_map(fn($r)=>$this->fullProjection($r),$records);if($this->reviewer($actor,$personnel,$records[0]['ranking_track_id']??null))return array_map(fn($r)=>$this->reviewerProjection($r),$records);throw new RuntimeException('RANK_HISTORY_ACCESS_DENIED');}
 public function compatibility(array$actor,string$personnel):array{$records=$this->db->table('personnel_approved_rank_records')->select('ranking_track_id')->where('personnel_profile_id',$personnel)->orderBy('recorded_at','DESC')->get()->getResultArray();if(!$this->isHr($actor)&&!$this->owner($actor,$personnel)&&!$this->reviewer($actor,$personnel,$records[0]['ranking_track_id']??null))throw new RuntimeException('RANK_HISTORY_ACCESS_DENIED');$profile=$this->db->table('personnel_profiles')->select('current_rank_title')->where('profile_id',$personnel)->get()->getRowArray();if(!$profile)throw new InvalidArgumentException('PERSONNEL_NOT_FOUND');return['current_present_rank'=>$profile['current_rank_title']?:null,'history_initialized'=>count($records)>0,'compatibility_state'=>count($records)>0?'canonical_history':'legacy_present_rank_only'];}
 private function fullProjection(array$r):array{$c=$this->correction($r['id']);unset($r['signed_document_storage_path'],$r['signed_document_sha256']);$r['correction']=$c;return$r;}private function reviewerProjection(array$r):array{return['approved_rank_code'=>$r['approved_rank_code'],'effectivity_date'=>$r['effectivity_date'],'status'=>$r['status']];}
 private function correction(string$id):?array{$c=$this->db->table('personnel_rank_corrections')->groupStart()->where('original_approved_rank_record_id',$id)->orWhere('corrected_approved_rank_record_id',$id)->groupEnd()->get()->getRowArray();return$c?:null;}private function document(array$o,?UploadedFile$f,bool$reuse,string$id):array{if($reuse)return['storage_path'=>$o['signed_document_storage_path'],'original_name'=>$o['signed_document_original_name'],'mime'=>$o['signed_document_mime_type'],'sha256'=>$o['signed_document_sha256'],'bytes'=>$o['signed_document_byte_size']];if(!$f||!$f->isValid())throw new InvalidArgumentException('CORRECTION_SUPPORTING_DOCUMENT_REQUIRED');$v=$this->storage->validateFile($f->getTempName(),$f->getClientName());if(!$v['success'])throw new InvalidArgumentException($v['error_code']);$s=$this->storage->storeFile($f->getTempName(),'approved-rank',$o['personnel_profile_id'],$id,$v['extension'],true);return['storage_path'=>$s['storage_path'],'original_name'=>$f->getClientName(),'mime'=>$s['detected_mime_type'],'sha256'=>$s['sha256'],'bytes'=>$s['byte_size']];}
 private function assertNoOverlap(array$o,array$h,string$from,?string$to,string$status):void{if(!in_array($status,['pending','current','historical'],true))return;$q=$this->db->table('personnel_rank_history')->where('personnel_profile_id',$o['personnel_profile_id'])->where('id !=',$h['id']);if($status==='pending'){$q->where('status','pending');}else{$q->whereIn('status',['pending','current','historical']);}$q->groupStart()->where('effective_to',null)->orWhere('effective_to >=',$from)->groupEnd();if($to!==null)$q->where('effective_from <=',$to);if($q->countAllResults()>0)throw new RuntimeException('CORRECTED_RANK_PERIOD_OVERLAP');}
 private function systemValidOption(array$o,string$code):bool{$review=$this->db->table('personnel_hr_final_rank_reviews')->where('id',$o['hr_final_rank_review_id'])->get()->getRowArray();if(!$review)return false;$decision=$this->db->table('personnel_recommended_rank_decisions')->where('id',$review['recommended_rank_decision_id'])->get()->getRowArray();$options=is_string($decision['valid_rank_options']??null)?json_decode($decision['valid_rank_options'],true):($decision['valid_rank_options']??[]);return in_array($code,array_column($options?:[],'rank_code'),true);}
 private function reviewer(array$a,string$p,?string$t):bool{try{$track=$t?$this->db->table('personnel_evaluation_periods')->where('id',$t)->get()->getRowArray():null;return$this->authority->actorMayAct($this->authority->resolveResponsibleAuthority($p,$track),(string)($a['profile']['id']??''));}catch(\Throwable){return false;}}private function notify(string$p,string$id,string$type,string$title,string$message):void{if($this->db->tableExists('notifications'))$this->db->table('notifications')->insert(['id'=>$this->uuid(),'recipient_profile_id'=>$p,'notification_type'=>$type,'title'=>$title,'message'=>$message,'reference_type'=>'personnel_approved_rank_records','reference_id'=>$id,'is_mandatory'=>1,'created_at'=>date('Y-m-d H:i:s')]);}
